CREATE TABLE morrow.users(id uuid PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE morrow.sessions(id uuid PRIMARY KEY, expires_at timestamptz NOT NULL, token text NOT NULL UNIQUE, user_id uuid NOT NULL REFERENCES morrow.users ON DELETE CASCADE, ip_address text, user_agent text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user ON morrow.sessions(user_id);
CREATE TABLE morrow.accounts(id uuid PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id uuid NOT NULL REFERENCES morrow.users ON DELETE CASCADE, password text, access_token text, refresh_token text, id_token text, access_token_expires_at timestamptz, refresh_token_expires_at timestamptz, scope text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider_id,account_id));
CREATE TABLE morrow.verifications(id uuid PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE morrow.rate_limits(id uuid PRIMARY KEY,key text NOT NULL UNIQUE,count integer NOT NULL,last_request bigint NOT NULL);
CREATE TABLE morrow.organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE CHECK(slug ~ '^[a-z0-9-]{3,60}$'),description text NOT NULL DEFAULT '',is_demo boolean NOT NULL DEFAULT false,retention_days integer NOT NULL DEFAULT 365 CHECK(retention_days BETWEEN 30 AND 3650),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE morrow.memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES morrow.organizations,user_id uuid NOT NULL REFERENCES morrow.users,role text NOT NULL CHECK(role IN ('admin','recruiter','manager','interviewer')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,user_id));
CREATE TABLE morrow.invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES morrow.organizations,email text NOT NULL,role text NOT NULL CHECK(role IN ('recruiter','manager','interviewer','admin')),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE morrow.departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES morrow.organizations,name text NOT NULL,UNIQUE(org_id,name),UNIQUE(org_id,id));
CREATE TABLE morrow.pipeline_stages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES morrow.organizations,name text NOT NULL,position integer NOT NULL,UNIQUE(org_id,name),UNIQUE(org_id,position),UNIQUE(org_id,id));
CREATE TABLE morrow.jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES morrow.organizations,title text NOT NULL,department_id uuid,manager_id uuid NOT NULL REFERENCES morrow.users,location text NOT NULL,workplace text NOT NULL CHECK(workplace IN ('Remote','Hybrid','On-site')),employment text NOT NULL CHECK(employment IN ('Full-time','Part-time','Contract','Internship')),openings integer NOT NULL CHECK(openings BETWEEN 1 AND 100),salary_min integer,salary_max integer,currency text NOT NULL DEFAULT 'USD',description text NOT NULL,requirements text NOT NULL DEFAULT '',skills text[] NOT NULL DEFAULT '{}',questions jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','approved','published','closed','archived')),closing_date date,created_by uuid NOT NULL REFERENCES morrow.users,approved_by uuid REFERENCES morrow.users,published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,UNIQUE(org_id,id),FOREIGN KEY(org_id,department_id) REFERENCES morrow.departments(org_id,id),CHECK(salary_min IS NULL OR salary_min>=0),CHECK(salary_max IS NULL OR salary_max>=salary_min));
CREATE INDEX jobs_org_status ON morrow.jobs(org_id,status,created_at DESC);
CREATE TABLE morrow.candidates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES morrow.organizations,user_id uuid NOT NULL REFERENCES morrow.users,name text NOT NULL,email text NOT NULL,phone text NOT NULL DEFAULT '',skills text[] NOT NULL DEFAULT '{}',experience text NOT NULL DEFAULT '',talent_consent boolean NOT NULL DEFAULT false,tags text[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,user_id),UNIQUE(org_id,id));
CREATE TABLE morrow.applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES morrow.organizations,job_id uuid NOT NULL,candidate_id uuid NOT NULL,stage text NOT NULL DEFAULT 'Applied',status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','rejected','withdrawn','hold','hired')),owner_id uuid REFERENCES morrow.users,source text NOT NULL DEFAULT 'Careers page',answers jsonb NOT NULL DEFAULT '{}',reason text,stage_entered_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,UNIQUE(job_id,candidate_id),UNIQUE(org_id,id),FOREIGN KEY(org_id,job_id) REFERENCES morrow.jobs(org_id,id),FOREIGN KEY(org_id,candidate_id) REFERENCES morrow.candidates(org_id,id));
CREATE INDEX applications_org_stage ON morrow.applications(org_id,status,stage,stage_entered_at);
CREATE INDEX applications_job ON morrow.applications(org_id,job_id,created_at DESC);
CREATE TABLE morrow.application_stage_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,application_id uuid NOT NULL,from_stage text,to_stage text NOT NULL,actor_id uuid NOT NULL REFERENCES morrow.users,reason text,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,application_id) REFERENCES morrow.applications(org_id,id));
CREATE TABLE morrow.documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,candidate_id uuid NOT NULL,name text NOT NULL,mime text NOT NULL,size integer NOT NULL CHECK(size BETWEEN 1 AND 2097152),content bytea NOT NULL,extracted_text text,parsing_status text NOT NULL CHECK(parsing_status IN ('pending','parsed','failed')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,candidate_id) REFERENCES morrow.candidates(org_id,id));
CREATE TABLE morrow.notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,application_id uuid NOT NULL,author_id uuid NOT NULL REFERENCES morrow.users,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,application_id) REFERENCES morrow.applications(org_id,id));
CREATE TABLE morrow.interviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,application_id uuid NOT NULL,interviewer_id uuid NOT NULL REFERENCES morrow.users,title text NOT NULL,type text NOT NULL DEFAULT 'Video',starts_at timestamptz NOT NULL,duration integer NOT NULL CHECK(duration BETWEEN 15 AND 240),timezone text NOT NULL,location text NOT NULL DEFAULT '',instructions text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','completed','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),FOREIGN KEY(org_id,application_id) REFERENCES morrow.applications(org_id,id));
CREATE INDEX interviews_schedule ON morrow.interviews(org_id,interviewer_id,starts_at) WHERE status='scheduled';
CREATE TABLE morrow.scorecards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,interview_id uuid NOT NULL,author_id uuid NOT NULL REFERENCES morrow.users,ratings jsonb NOT NULL,body text NOT NULL,recommendation text NOT NULL CHECK(recommendation IN ('Strong yes','Yes','Discuss','No')),submitted boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(interview_id,author_id),FOREIGN KEY(org_id,interview_id) REFERENCES morrow.interviews(org_id,id));
CREATE TABLE morrow.tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES morrow.organizations,application_id uuid,assignee_id uuid NOT NULL REFERENCES morrow.users,title text NOT NULL,due_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','done')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,application_id) REFERENCES morrow.applications(org_id,id));
CREATE INDEX tasks_org_due ON morrow.tasks(org_id,status,due_at);
CREATE TABLE morrow.messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,application_id uuid NOT NULL,author_id uuid NOT NULL REFERENCES morrow.users,body text NOT NULL,state text NOT NULL CHECK(state IN ('draft','portal','pending_email')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,application_id) REFERENCES morrow.applications(org_id,id));
CREATE TABLE morrow.offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,application_id uuid NOT NULL UNIQUE,compensation integer NOT NULL CHECK(compensation>0),currency text NOT NULL,start_date date NOT NULL,expires_at timestamptz NOT NULL,terms text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','approved','available','accepted','declined','expired')),created_by uuid NOT NULL REFERENCES morrow.users,approved_by uuid REFERENCES morrow.users,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,application_id) REFERENCES morrow.applications(org_id,id));
CREATE TABLE morrow.audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES morrow.organizations,actor_id uuid NOT NULL REFERENCES morrow.users,entity_type text NOT NULL,entity_id uuid NOT NULL,action text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',public boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_org ON morrow.audit_events(org_id,created_at DESC);
CREATE TABLE morrow.submission_limits(key text PRIMARY KEY,count integer NOT NULL,window_start timestamptz NOT NULL);
CREATE INDEX candidates_search ON morrow.candidates USING gin(to_tsvector('simple',name || ' ' || email || ' ' || experience));
CREATE INDEX jobs_search ON morrow.jobs USING gin(to_tsvector('simple',title || ' ' || description));
